  from: from_label,
  to: to_label,
  changes: {
    added: added_arr.map do |c| change_to_json_hash(c) end,
    removed: removed_arr.map do |c| change_to_json_hash(c) end,
    updated: updated_arr.map do |c| change_to_json_hash(c) end,
  },
  summary: {
