Log.with_context do
  Log.context.set(package: dependency.name)
  check_single_resolver_by_name(dependency.resolver)

  __temp_a7004145_3 = {dependency.name, dependency.requirement}
  @search_results[__temp_a7004145_3]? || (
    @search_results[__temp_a7004145_3] = begin
      resolver = dependency.resolver
      versions = (Versions.sort(versions_for(dependency, resolver))).reverse
      result = versions.map do |version|
        __temp_a7004145_1 = {dependency.name, version}
        @specs[__temp_a7004145_1]? || (
          @specs[__temp_a7004145_1] = begin
            (resolver.spec(version)).tap do |spec|
              spec.version = version
            end
          end
        )
      end

      result
    end
  )
end

@ignored_count = 0
@filtered_count = 0

@results.map do |result|
  filtered_vulns = result.vulnerabilities.select do |vuln|
    active_ignore = @ignore_rules.find do |rule| (rule.id == vuln.id) && rule.active? end
    if active_ignore
      @ignored_count = @ignored_count + 1
      next false
    end


    alias_ignored = vuln.aliases.any? do |a| @ignore_rules.any? do |rule| (rule.id == a) && rule.active? end end
    if alias_ignored
      @ignored_count = @ignored_count + 1
      next false
    end

    if vuln.severity.at_or_above?(@min_severity)
      true
    else
      @filtered_count = @filtered_count + 1
      false
    end
  end

  PackageScanResult.new(result.package, result.purl, filtered_vulns)
end
